def cp_als(T, r, iters=40, seed=0):
    rng=np.random.default_rng(seed); I,J,C=T.shape
    A=rng.normal(size=(I,r))/np.sqrt(I); B=rng.normal(size=(J,r))/np.sqrt(J); Cc=rng.normal(size=(C,r))
    for it in range(iters):
        Z=(B[:,None,:]*Cc[None,:,:]).reshape(J*C,r); A=np.linalg.lstsq(Z, T.reshape(I,J*C).T, rcond=None)[0].T
        Z=(A[:,None,:]*Cc[None,:,:]).reshape(I*C,r); B=np.linalg.lstsq(Z, T.transpose(1,0,2).reshape(J,I*C).T, rcond=None)[0].T
        Z=(A[:,None,:]*B[None,:,:]).reshape(I*J,r); Cc=np.linalg.lstsq(Z, T.reshape(I*J,C), rcond=None)[0].T
    return A,B,Cc
